def pcs(rows):
  """Every topping on the tray: (leftmost column, letter); a piece is 2 cells wide."""
  return [(m.start(), m.group()[0]) for row in rows for m in re.finditer(r"([a-z])\1", row)]

def cutb(r, T, n):
  """A random cutting of a T-wide tray into n slices, each at least 3 wide."""
  if n < 2:
    return []
  b = []
  t = p = 0
  for x in sorted(r.sample(range(T - 2 * n - 1), n - 1)):
    t += x - p + 3
    p = x + 1
    b.append(t)
  return b

def side(P, x, lo, hi):
  """(pieces of x this slice holds, how many of them lie whole inside it)."""
  a = w = 0
  for c, L in P:
    if L == x and c + 1 >= lo and c < hi:
      a += 1
      w += c >= lo and c + 1 < hi
  return a, w

def pairb(r, P, X, T, x, nmax):
  """A cutting carrying the picture: the knife through a piece of x and a WHOLE piece
  of x just inside the slice on each side.  Random cuts almost never do it."""
  f = r.choice(X) + 1
  los = [l for l in range(max(0, f - 15), f - 2) if (l == 0 or l > 2) and side(P, x, l, f) == (2, 1)]
  his = [h for h in range(f + 3, min(T, f + 16) + 1) if (h == T or T - h > 2) and side(P, x, f, h) == (2, 1)]
  if not los or not his:
    return None
  lo = r.choice(los)
  hi = r.choice(his)
  opt = [(i, j) for i in range(min(lo // 3, 5) + 1) for j in range(min((T - hi) // 3, 5) + 1)
         if 2 <= i + j <= min(6, nmax - 2)]
  if not opt:
    return None
  n1, n2 = r.choice(opt)
  return (cutb(r, lo, n1) + ([lo] if lo else []) + [f] + ([hi] if hi < T else [])
          + [hi + y for y in cutb(r, T - hi, n2)])

def per(P, x, b):
  """Pieces of x per slice (a halved one counts on both sides); how many lie whole in."""
  A = [0] * (len(b) + 1)
  Wh = list(A)
  for c, L in P:
    if L == x:
      i = bisect.bisect_right(b, c)
      j = bisect.bisect_right(b, c + 1)
      A[i] += 1
      if i == j:
        Wh[i] += 1
      else:
        A[j] += 1
  return A, Wh

def halves(P, b, x, A, Wh):
  """(the picture, the left-only reading, the right-only reading, two of any topping).
  THE PICTURE: a piece of x the knife halved with a COUNTED slice on BOTH sides of it,
  each of them holding two only because of its half - so each half is plainly counted
  for its own side.  2 = both sides are like that, 1 = one is, 0 = not there."""
  best = 0
  Lf = list(Wh)
  Rt = list(Wh)
  q = {}
  for c, L in P:
    i = bisect.bisect_right(b, c)
    j = bisect.bisect_right(b, c + 1)
    for t in {i, j}:
      q[t, L] = q.get((t, L), 0) + 1
    if L != x or i == j:
      continue
    Lf[i] += 1
    Rt[j] += 1
    if A[i] > 1 and A[j] > 1:
      best = max(best, (A[i] == 2 and Wh[i] == 1) + (A[j] == 2 and Wh[j] == 1))
  return (best, sum(v > 1 for v in Lf), sum(v > 1 for v in Rt),
          len({t for t, L in q if q[t, L] > 1}))

def grade(P, b, T, x, tot, k, A, Wh):
  """How loudly this cutting says the rule, 0 (best) to 6.  0 = the halved piece with a
  counted slice on both sides, each holding a whole piece and that half; an UNCOUNTED
  slice with a lone whole piece ("one is not enough"); a slice of three ("exactly two"
  is visibly not the rule); no rival reading coming to k.  5 = a structural rival (cuts,
  slices, severed, whole pairs, slices touched) comes to k; 4 = no uncounted lone whole
  piece; 3 = a one-sided halves reading or "two of any one topping" does; 2 = only one
  side needs its half; 1 = no slice of three; 6 = no picture at all."""
  w = [q - p for p, q in zip([0] + b, b + [T])]
  if min(w) > 4 or max(w) - min(w) < 5:      # visibly hand-cut, so neatness is not it
    return 6
  h, lf, rt, an = halves(P, b, x, A, Wh)
  if not h:
    return 6
  if (k in (len(A), len(A) - 1) or tot - sum(Wh) == k or sum(v > 1 for v in Wh) == k
      or sum(1 for v in A if v) == k):
    return 5
  if not any(A[i] == 1 and Wh[i] == 1 for i in range(len(A))):
    return 4
  if k in (lf, rt, an):
    return 3
  return 2 if h == 1 else 1 - (max(A) > 2)

def ren(lines, b):
  return "\n".join("".join("|" + c if i in b else c for i, c in enumerate(row))
                   for row in lines)

def solve(clue):
  a = clue.split("\n")
  q, p = (a[-1], a[:-1]) if "slice" in a[-1] else (a[0], a[1:])   # v6 last, v5 first
  x = q[0]
  k = int(q[2])
  if not k:
    return "\n".join(p)              # "0 slices": the knife stays in the drawer
  rows = [l for l in p if ":" in l]
  T = len(rows[0])
  nmax = T // 3
  P = pcs(rows)
  X = [c for c, L in P if L == x]
  tot = len(X)
  r = random.Random(q + "\n" + "\n".join(p))   # v5's line order: v5's cutting
  hold = (9, None)
  for it in range(30000):
    if it > (2000 if hold[0] < 2 else 12000):
      break
    b = cutb(r, T, r.randint(4, 8)) if it % 4 == 3 else pairb(r, P, X, T, x, nmax)
    if not b:
      continue
    A, Wh = per(P, x, b)
    if sum(1 for v in A if v > 1) != k:
      continue
    g = grade(P, b, T, x, tot, k, A, Wh)
    if not g:
      return ren(p, set(b))
    if g < hold[0]:
      hold = (g, b)
  return ren(p, set(hold[1])) if hold[1] else ""

